    return function(a,b){
        var value1 = a[prop];
        var value2 = b[prop];
        return value1 - value2;
    }
}
result=result.replace(/<s0,(.+?)<\/s>/gi, '$1!');

var arr = result.split('!');
var arr3 = [];

for(var i=0; i<arr.length-1; i++){
    var arr2 = arr[i].split('>');
  arr3[i] = { 
  xy: Number(arr2[0]), 
  word: arr2[1] };
}

arr3.sort(cmp('xy'));

var str="";
for (var i = 0; i<arr3.length; i++) {
     if (arr3[i].word == "")
           { str += "\n";}
   else {
    str += arr3[i].word;   
      }
}
str;
</js>
